# Fusion Intelligence Engine & Anomaly Explanation
class IncidentAnalyzer:
    def __init__(self, ollama_host: str = "http://localhost:11434"):
        self.client = OllamaClient(host=ollama_host)
        self.prompt_template = """
You are an autonomous AIOps engineer analyzing an anomaly event.
Observed Telemetry Vector:
- Isolation Forest Score: {risk_score} (Threshold: 0.85)
- Telemetry Drift: {drift_params}
- Log Sample: {log_sample}

Analyze the telemetry failure mode, identify root causes, and propose recovery actions.
"""
    async def explain_anomaly(self, incident: IncidentData) -> AnalysisReport:
        prompt = self.prompt_template.format(
            risk_score=incident.score,
            drift_params=incident.metrics,
            log_sample=incident.logs[:3]
        )
        response = await self.client.generate(model="mistral:instruct", prompt=prompt)
        return AnalysisReport(verdict=response.summary, action_items=response.remediation)
